func tb0(v *Word) any {
	if v == nil {
		return nil
	}
	return TSetNodeType(TBack(&v.TNode), tnt[5])
}

func tb1(v *Marker) any {
	if v == nil {
		return nil
	}
	return TSetNodeType(TBack(&v.TNode), tnt[3])
}

